<aside class="widget-preview" aria-label="Live widget appearance preview">
    <div class="widget-preview-heading"><strong>Live preview</strong><span>Unsaved changes</span></div>
    <p class="text-xs text-white/50 mb-4">Appearance demo only · no coins used. Save to update the live widget.</p>
    <div class="widget-demo-stage" id="widget-demo-stage">
        <div class="widget-demo-window" id="widget-demo-window">
            <header><span class="widget-demo-avatar">✦</span><div><strong id="widget-demo-name"></strong><small>AI assistant · sample conversation</small></div></header>
            <div class="widget-demo-messages"><p class="widget-demo-bubble" id="widget-demo-greeting"></p><p class="widget-demo-user">How can you help me?</p><p class="widget-demo-bubble">I can answer questions using the knowledge selected for this agent.</p></div>
            <div class="widget-demo-input"><span id="widget-demo-placeholder"></span><span aria-hidden="true">➤</span></div>
            <small id="widget-demo-brand">Powered by Sayzio</small>
        </div>
        <div class="widget-demo-launcher" id="widget-demo-launcher">✦ <span></span></div>
    </div>
    <p class="text-xs text-white/50 mt-3" id="widget-demo-placement"></p>
</aside>
@push('scripts')
<script>
(function(){var f=document.getElementById('widget-editor');if(!f)return;
function value(n){return f.elements[n]?.value||'';}function checked(n){return !!f.querySelector('input[type=checkbox][name="'+n+'"]:checked');}
function refresh(){var stage=document.getElementById('widget-demo-stage'),w=document.getElementById('widget-demo-window'),accent=value('config[accent]');if(!/^#[0-9a-f]{6}$/i.test(accent))accent='#3d6bff';stage.style.setProperty('--demo-accent',accent);var theme=value('config[theme]');stage.classList.toggle('demo-dark',theme==='dark'||theme==='auto'&&matchMedia('(prefers-color-scheme:dark)').matches);var placement=f.querySelector('input[name=placement]:checked')?.value||'biolink';stage.dataset.placement=placement;stage.classList.toggle('demo-left',value('config[position]')==='bottom-left');stage.classList.toggle('demo-inline',checked('config[inline]')&&placement==='biolink');document.getElementById('widget-demo-name').textContent=value('name')||'Your assistant';document.getElementById('widget-demo-greeting').textContent=value('config[greeting_bubble]')||'Hi! How can I help?';document.getElementById('widget-demo-placeholder').textContent=value('config[placeholder]')||'Ask me anything…';document.querySelector('#widget-demo-launcher span').textContent=value('config[launcher_label]')||'Chat';document.getElementById('widget-demo-brand').hidden=!checked('config[show_branding]');document.getElementById('widget-demo-placement').textContent=placement==='inbox'?'Inbox preview: replies appear as messages in your conversations.':placement==='page'?'Full-page chat preview.':placement==='embed'?'Website embed preview. Domain restrictions apply after saving.':'Link in Bio preview. Add the widget block to a permitted page.';}

var originalRefresh=refresh;refresh=function(){originalRefresh();var stage=document.getElementById('widget-demo-stage');['accent','chat','user','assistant'].forEach(function(part){var mode=value('config['+part+'_mode]'),color=value('config['+part+'_color]'),end=value('config['+part+'_color_end]'),text=value('config['+part+'_text]'),image=value('config['+part+'_image]');stage.style.removeProperty('--cmp-'+part+'-bg');stage.style.removeProperty('--cmp-'+part+'-text');if(mode==='default'||!/^#[0-9a-f]{6}$/i.test(color))return;var bg=color;if(mode==='gradient'&&/^#[0-9a-f]{6}$/i.test(end))bg='linear-gradient(135deg,'+color+','+end+')';if(mode==='image'){try{var u=new URL(image);if(!['http:','https:'].includes(u.protocol))return;bg=color+' url('+JSON.stringify(u.href)+') center/cover';}catch(e){return;}}stage.style.setProperty('--cmp-'+part+'-bg',bg);if(/^#[0-9a-f]{6}$/i.test(text))stage.style.setProperty('--cmp-'+part+'-text',text);});stage.style.setProperty('--cmp-radius',(Number(value('config[bubble_radius]'))||14)+'px');};
f.addEventListener('input',refresh);f.addEventListener('change',refresh);refresh();})();
</script>
@endpush
<style>
.widget-page{max-width:none;margin:0;padding:0}.widget-editor-grid{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(300px,1fr);gap:24px;align-items:start}.widget-tabs{display:flex;gap:8px;flex-wrap:wrap;border-bottom:1px solid var(--border-color,#dbe2ef);padding-bottom:14px}.widget-tabs button{padding:9px 16px;border-radius:10px;font-size:13px;color:var(--text-secondary,#9299aa)}.widget-tabs button[aria-pressed=true]{background:#3454ef;color:white}.widget-preview{position:sticky;top:24px;padding:20px;border:1px solid var(--border-color,#dbe2ef);border-radius:20px;background:var(--bg-card,#fff)}.widget-preview-heading{display:flex;justify-content:space-between;gap:10px;margin-bottom:8px}.widget-preview-heading span{font-size:10px;color:#9299aa}.widget-demo-stage{--demo-accent:#3d6bff;padding:20px 12px;min-height:430px;border-radius:16px;background:repeating-linear-gradient(0deg,transparent,transparent 23px,#dbe2ef66 24px),#f1f4f9;display:flex;flex-direction:column;align-items:flex-end;gap:14px}.widget-demo-window{width:100%;max-width:330px;border-radius:16px;overflow:hidden;background:#fff;color:#17213a;box-shadow:0 10px 32px #17213a26;border:1px solid #dbe2ef}.widget-demo-window header{display:flex;align-items:center;gap:10px;padding:16px;background:var(--demo-accent);color:#fff}.widget-demo-window header strong{font-size:13px;display:block;overflow-wrap:anywhere}.widget-demo-window header small{display:block;font-size:10px;opacity:.8}.widget-demo-avatar{font-size:24px}.widget-demo-messages{display:grid;gap:12px;padding:16px;font-size:12px}.widget-demo-bubble{margin:0;padding:10px;border-radius:10px;background:#f0f2f7;max-width:90%;white-space:pre-wrap;overflow-wrap:anywhere}.widget-demo-user{justify-self:end;background:var(--demo-accent);color:white;padding:10px;border-radius:10px;margin:0}.widget-demo-input{margin:0 12px 12px;padding:10px;display:flex;gap:8px;justify-content:space-between;border:1px solid #dbe2ef;border-radius:10px;font-size:11px;color:#9299aa;overflow-wrap:anywhere}.widget-demo-window>small{display:block;text-align:center;font-size:9px;padding-bottom:10px;color:#9299aa}.widget-demo-window>small[hidden]{display:none}.widget-demo-launcher{border-radius:24px;padding:10px 16px;background:var(--demo-accent);color:white;font-size:12px;max-width:100%;overflow-wrap:anywhere}.demo-left{align-items:flex-start}.demo-dark .widget-demo-window{background:#171d2a;color:#e4e9f3;border-color:#374155}.demo-dark .widget-demo-bubble{background:#293244}.demo-dark .widget-demo-input{border-color:#374155}.widget-demo-stage[data-placement=page] .widget-demo-window,.demo-inline .widget-demo-window{max-width:none}.widget-demo-stage[data-placement=page] .widget-demo-launcher,.widget-demo-stage[data-placement=inbox] .widget-demo-launcher,.demo-inline .widget-demo-launcher{display:none}.widget-page input:not([type=radio]):not([type=checkbox]):not([type=color]),.widget-page select{background:var(--bg-glass-input)!important}@media(max-width:1050px){.widget-editor-grid{grid-template-columns:1fr}.widget-preview{position:static}.widget-demo-stage{align-items:center}}[x-cloak]{display:none!important}
</style>

<style>.widget-demo-window header,.widget-demo-launcher{background:var(--cmp-accent-bg,var(--demo-accent));color:var(--cmp-accent-text,#fff)}.widget-demo-messages{background:var(--cmp-chat-bg,transparent);color:var(--cmp-chat-text,inherit)}.widget-demo-user{background:var(--cmp-user-bg,var(--demo-accent));color:var(--cmp-user-text,#fff);border-radius:var(--cmp-radius,14px)}.widget-demo-stage .widget-demo-bubble{background:var(--cmp-assistant-bg,#f0f2f7);color:var(--cmp-assistant-text,#17213a);border-radius:var(--cmp-radius,14px)}.widget-demo-stage.demo-dark .widget-demo-bubble{background:var(--cmp-assistant-bg,#293244);color:var(--cmp-assistant-text,#e4e9f3)}</style>
